/* 屏幕常亮 —— 进入播放界面后阻止手机 / 电脑息屏、锁屏
 *
 * 两级方案（自动选择，用户无感）：
 *   1. Screen Wake Lock API：系统级常亮，但只在 HTTPS / localhost 下可用
 *      （本站是 http://IP 访问，属于非安全上下文，此路通常不可用）
 *   2. 隐藏的静音循环视频：NoSleep.js 的经典方案，HTTP 下同样可用，
 *      浏览器在播放视频时会阻止屏幕进入休眠，iOS Safari 也适用
 *
 * 另外：页面切到后台再回来、或系统因省电释放了锁时会自动重新申请。
 * 默认开启，用户可点播放器上的「常亮」按钮关闭以省电，偏好存 localStorage。
 *
 * 视频数据来自 NoSleep.js v0.12.0 (MIT License, Rich Tibbett)
 * https://github.com/richtr/NoSleep.js
 */
(() => {
  'use strict';

  const LS_KEY = 'cloudmedia.keepawake.v1';
  const SOURCES = [
    ['video/webm', 'data:video/webm;base64,'],
    ['video/mp4',  'data:video/mp4;base64,']
  ];

  let wanted = true;          // 用户是否希望常亮
  let sentinel = null;        // WakeLockSentinel
  let video = null;           // 兜底用的隐藏视频
  let mode = 'off';           // wakelock | video | off | unsupported
  let listeners = [];
  let gestureBound = false;

  try {
    const saved = localStorage.getItem(LS_KEY);
    if (saved === 'off') wanted = false;
  } catch {}

  function persist() {
    try { localStorage.setItem(LS_KEY, wanted ? 'on' : 'off'); } catch {}
  }
  function snapshot() {
    return {
      enabled: wanted,
      active: mode === 'wakelock' || mode === 'video',
      mode: mode,
      label: mode === 'wakelock' ? '系统级常亮'
           : mode === 'video'    ? '兼容模式常亮'
           : mode === 'unsupported' ? '浏览器不支持'
           : '已关闭'
    };
  }
  function emit() {
    const s = snapshot();
    listeners.forEach((fn) => { try { fn(s); } catch {} });
    // 同步所有带 data-keepawake 的按钮
    document.querySelectorAll('[data-keepawake]').forEach((btn) => {
      btn.classList.toggle('active', s.active);
      btn.setAttribute('aria-pressed', s.active ? 'true' : 'false');
      btn.title = s.active
        ? '屏幕常亮已开启（' + s.label + '）· 点击关闭'
        : (s.enabled ? '正在尝试保持屏幕常亮…点击关闭' : '屏幕常亮已关闭 · 点击开启');
    });
  }

  function makeVideo() {
    if (video) return video;
    video = document.createElement('video');
    video.setAttribute('playsinline', '');
    video.setAttribute('muted', '');
    video.setAttribute('aria-hidden', 'true');
    video.muted = true;
    video.loop = true;
    video.style.cssText = 'position:fixed;left:-10px;top:-10px;width:1px;height:1px;opacity:0;pointer-events:none;';
    SOURCES.forEach(([type, src]) => {
      const s = document.createElement('source');
      s.src = src; s.type = type;
      video.appendChild(s);
    });
    // 视频不足 1 秒时 loop 即可；超过则手动回绕，避免播放结束
    video.addEventListener('loadedmetadata', () => {
      if (video.duration > 1) {
        video.loop = false;
        video.addEventListener('timeupdate', () => {
          if (video.currentTime > 0.5) { try { video.currentTime = 0; } catch {} }
        });
      }
    });
    (document.body || document.documentElement).appendChild(video);
    return video;
  }

  let acquiring = false;
  async function acquire() {
    if (!wanted || document.hidden || acquiring) return;
    acquiring = true;
    try {
      // 1) 系统级 Wake Lock（HTTPS / localhost）
      if ('wakeLock' in navigator) {
        try {
          if (sentinel && !sentinel.released) return;
          sentinel = await navigator.wakeLock.request('screen');
          mode = 'wakelock';
          sentinel.addEventListener('release', () => {
            sentinel = null;
            if (wanted) { mode = 'off'; emit(); setTimeout(acquire, 300); }
            else { mode = 'off'; emit(); }
          });
          // 成功后再启动兜底视频没必要，直接返回
          emit();
          return;
        } catch (e) {
          // 非安全上下文 / 低电量 / 省电模式：落到视频兜底
        }
      }
      // 2) 隐藏静音视频（HTTP 下也能阻止息屏）
      try {
        const v = makeVideo();
        await v.play();
        mode = 'video';
        emit();
        return;
      } catch (e) {
        mode = 'unsupported';
        emit();
        bindGesture();   // 需要用户手势才能起播时，等第一次交互再试
      }
    } finally {
      acquiring = false;
    }
  }

  function release() {
    if (sentinel) {
      try { sentinel.release(); } catch {}
      sentinel = null;
    }
    if (video) { try { video.pause(); } catch {} }
    mode = 'off';
    emit();
  }

  // iOS 等浏览器要求用户手势才能起播静音视频，首次交互后再试一次
  function bindGesture() {
    if (gestureBound) return;
    gestureBound = true;
    const retry = () => {
      if (wanted && mode !== 'wakelock' && mode !== 'video') acquire();
    };
    ['pointerdown', 'touchstart', 'keydown'].forEach((ev) =>
      document.addEventListener(ev, retry, { passive: true }));
  }

  function enable() { wanted = true; persist(); emit(); acquire(); }
  function disable() { wanted = false; persist(); release(); }
  function toggle() { wanted ? disable() : enable(); }

  // 页面重新可见：Wake Lock 会被系统自动释放，需要重新申请；视频也可能被暂停
  document.addEventListener('visibilitychange', () => {
    if (document.hidden) return;
    if (!wanted) return;
    if (video && video.paused) { mode = 'off'; }
    setTimeout(acquire, 150);
  });
  window.addEventListener('pagehide', release);

  // 按钮接线（支持多个同名按钮）
  function wire() {
    document.querySelectorAll('[data-keepawake]').forEach((btn) => {
      if (btn.dataset.wired) return;
      btn.dataset.wired = '1';
      btn.addEventListener('click', toggle);
    });
    emit();
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => { wire(); acquire(); });
  } else {
    wire();
    acquire();
  }

  window.ScreenKeeper = {
    enable, disable, toggle,
    state: snapshot,
    onChange: (fn) => { listeners.push(fn); try { fn(snapshot()); } catch {} }
  };
})();
